WITH FilteredSuppliers AS (SELECT * FROM suppliers WHERE (city = 'New York' AND city = 'New York') OR city = 'Singapore'), country_group_summary AS (SELECT CASE WHEN country IN ('JP', 'UK') THEN 'tier_1' ELSE 'other' END AS country_group, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(country))) AS country_values FROM FilteredSuppliers GROUP BY CASE WHEN country IN ('JP', 'UK') THEN 'tier_1' ELSE 'other' END) SELECT * FROM country_group_summary ORDER BY country_group
